/** Tournament templates (static config). Instances are generated by schedule.ts. */
import type { RankMode } from "./scoring";

export type TGame = "buckshot" | "slot" | "roulette" | "blackjack" | "craps";
export type PrizeType = "cash" | "bonus";
export const SUPPORTED_GAMES: readonly TGame[] = ["buckshot", "slot", "roulette", "blackjack", "craps"];

export const GAME_INFO: Record<TGame, { name: string; href: string; category: "slots" | "tables"; unit: string; minBet: number; maxBet: number }> = {
  buckshot: { name: "Buckshot Bars", href: "/buckshot", category: "slots", unit: "spins", minBet: 25, maxBet: 500 },
  slot: { name: "Sundown Trail", href: "/slot", category: "slots", unit: "spins", minBet: 225, maxBet: 450 },
  roulette: { name: "Roulette", href: "/roulette", category: "tables", unit: "spins", minBet: 25, maxBet: 500 },
  // Spec §5.3 scaled to the $100 stack: Chip Race 10–200 of 1,000 → $1–$20 a hand (doubles and
  // splits may go past the max, within the stack); Hot Roll 5–100 → 50¢–$10 of NEW action per roll.
  blackjack: { name: "Blackjack", href: "/blackjack", category: "tables", unit: "hands", minBet: 100, maxBet: 2000 },
  craps: { name: "Craps", href: "/craps", category: "tables", unit: "rolls", minBet: 50, maxBet: 1000 },
};

/** Fixed-play table formats (spec §5.3): the game decides the format, mode and number of plays. */
export const TABLE_FORMATS: Partial<Record<TGame, { format: string; mode: RankMode; fixedPlays: number; short: string }>> = {
  blackjack: { format: "Blackjack Chip Race", mode: "balance", fixedPlays: 30, short: "Chip Race · 30 hands" },
  craps: { format: "Craps Hot Roll", mode: "accumulated", fixedPlays: 40, short: "Hot Roll · 40 rolls" },
};

export type Template = {
  id: string;
  name: string;
  format: string;
  /** Chicago local start hours. */
  hours: number[];
  durationMin: number;
  games: TGame[];
  modes: RankMode[];
  /** Buy-in rotation (cents); 0 = freeroll. */
  buyins: number[];
  /** House-funded pool on freerolls (counted against the $50/day cap). */
  seedCents: number;
  /** Prize currency for paid instances and for free instances. */
  paidPrize: PrizeType;
  freePrize: PrizeType;
  startStackCents: number;
  rebuys: boolean;
  /** Name per game for rotating templates ("Happy Hour Blackjack"). */
  names?: Partial<Record<TGame, string>>;
  /** Rotate games in order by day and slot instead of a seeded pick. */
  rotate?: boolean;
  /** Freeroll budget priority: lower goes first when the $50/day cap is applied (default 10). */
  capPriority?: number;
};

const STACK = 10_000;

